public static int digitSum(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

public static int firstHarshad(int start) {
    int k = start;
    while (k % digitSum(k) != 0) {
        k++;
    }
    return k;
}

public class Battery {
    private int level;
    private int cycles;

    public Battery(int startLevel) {
        level = startLevel;
        cycles = 0;
    }

    public int use(int amount) {
        int used = Math.min(amount, level);
        level -= used;
        return used;
    }

    public void recharge() {
        level = 100;
        cycles++;
    }

    public int getLevel() { return level; }

    public int getCycles() { return cycles; }

    public boolean isLow() { return level < 20; }
}

public static void removeLaterDuplicates(ArrayList<String> names) {
    for (int i = 0; i < names.size(); i++) {
        int j = i + 1;
        while (j < names.size()) {
            if (names.get(j).equals(names.get(i))) {
                names.remove(j);
            } else {
                j++;
            }
        }
    }
}

public static int[] columnMins(int[][] grid) {
    int[] mins = new int[grid[0].length];
    for (int c = 0; c < grid[0].length; c++) {
        int min = grid[0][c];
        for (int r = 1; r < grid.length; r++) {
            if (grid[r][c] < min) {
                min = grid[r][c];
            }
        }
        mins[c] = min;
    }
    return mins;
}
